"kind": "propose",
"summary": "The current revision's OOM kills indicate a memory limit regression. Increasing the memory limit for the app container is needed.",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_regression",
    "summary": "The current revision's memory limit is too low, as the app reached 100% of its 512Mi limit and was OOMKilled.",
    "supporting": ["ev-pod_states", "ev-container_memory", "ev-rollout_history"],
    "contradicting": [],
    "missing": ["ev-revision_health for revision 1's memory usage"],
    "status": "supported"
  },
  {
    "root_cause_class": "application_bug",
    "summary": "The new image may have a memory leak or increased memory usage, causing OOMKilled despite the same limit.",
    "supporting": ["ev-rollout_history", "ev-pod_states"],
    "contradicting": [],
    "missing": ["container_logs_tail to confirm memory usage patterns"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "checkout",
    "uid": "uid-deployment-checkout"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "640Mi"
        }
      }
    }
  },
  "expected_effect": "The increased memory limit should prevent OOMKilled errors by allowing the app to use more memory without being terminated.",
  "rationale": "The app reached 100% of its 512Mi memory limit and was OOMKilled. Increasing the limit by 25% (to 640Mi) provides a buffer for higher memory usage, addressing the memory limit regression identified in the current revision.",
  "cited_evidence_ids": ["ev-container_memory", "ev-pod_states", "ev-rollout_history"],
  "cited_predicates": ["oom_killed_new_revision", "oom_killed_current_revision", "memory_at_limit_before_kill", "failure_onset_after_rollout"]
}
}
